import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  texture,
  vec2,
  vec3,
  vec4,
  mix,
  smoothstep,
  uniform,
  float,
  fract,
  sin,
  dot,
  length,
  Fn,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'features-card-2-accent';

  // Source rect defines native aspect (512x320 -> 1.6:1). Keep the sprite
  // as a modest decorative accent element, not a hero subject.
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const baseHeight = 1.05;
  const baseWidth = baseHeight * aspect;

  const geometry = new PlaneGeometry(baseWidth, baseHeight, 1, 1);

  const opacityUniform = uniform(0.0);
  const mapUniform = { texture: null };

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });

  const uvNode = uv();

  // Engineered gradient tint: subtle vertical blend from ink to surface,
  // biased toward the edges so the accent stays legible against the card.
  const inkColor = vec3(0.086, 0.086, 0.114);
  const surfaceColor = vec3(0.043, 0.043, 0.063);
  const accentColor = vec3(1.0, 0.165, 0.22);

  const gradientMix = smoothstep(float(0.0), float(1.0), uvNode.y);
  const gradientTint = mix(surfaceColor, inkColor, gradientMix);

  // Subtle static grain (no time dependency — composition is static per spec).
  const grainFn = Fn(([coord]) => {
    const n = fract(sin(dot(coord, vec2(12.9898, 78.233))).mul(43758.5453));
    return n;
  });
  const grain = grainFn(uvNode.mul(600.0)).sub(0.5).mul(0.035);

  // Soft radial vignette so the accent reads as a floating glow, not a hard rect.
  const centered = uvNode.sub(vec2(0.5, 0.5));
  const dist = length(centered);
  const vignette = smoothstep(float(0.65), float(0.15), dist);

  material.colorNode = vec4(1.0, 1.0, 1.0, 1.0); // placeholder, replaced once texture loads

  const mesh = new Mesh(geometry, material);
  mesh.renderOrder = 5;
  root.add(mesh);

  function buildColorNode(mapTex) {
    if (!mapTex) return;
    mapTex.colorSpace = mapTex.colorSpace ?? undefined;
    const texNode = texture(mapTex, uvNode);
    const tinted = mix(texNode.rgb, mix(texNode.rgb, gradientTint, 0.12), 0.5);
    const withAccentEdge = mix(tinted, accentColor, vignette.mul(0.06));
    const withGrain = withAccentEdge.add(vec3(grain, grain, grain));
    const alpha = texNode.a.mul(vignette.mul(0.25).add(0.75)).mul(opacityUniform);
    material.colorNode = vec4(withGrain, alpha);
    material.needsUpdate = true;
  }

  let disposedTexture = null;

  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      disposedTexture = tex;
      mapUniform.texture = tex;
      buildColorNode(tex);
    })
    .catch(() => {
      // fail-soft: keep a flat surface tint if the texture cannot load
      const fallback = mix(surfaceColor, accentColor, vignette.mul(0.08));
      material.colorNode = vec4(fallback, opacityUniform.mul(0.9));
      material.needsUpdate = true;
    });

  // Billboard toward the active camera each frame.
  mesh.onBeforeRender = (renderer, scene, camera) => {
    root.quaternion.copy(camera.quaternion);
  };

  // Weighted, restrained entrance — static composition, so this fires once.
  root.position.set(0, -0.3 + 0.15, 0);
  root.scale.setScalar(0.97);

  const tl = gsap.timeline();
  tl.to(root.position, {
    y: -0.3,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    opacityUniform,
    {
      value: 1.0,
      duration: 0.6,
      ease: 'power2.out',
      onUpdate: () => {
        material.needsUpdate = true;
      },
    },
    0
  );
  tl.to(
    root.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0.05
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(opacityUniform);
    geometry.dispose();
    material.dispose();
    if (disposedTexture && typeof disposedTexture.dispose === 'function') {
      disposedTexture.dispose();
    }
  };

  return root;
}
